00149 function raw_db_list_table_fields_def($tablename, $type = false)
00150 {
00151   $result = db_query("SELECT sql FROM sqlite_master WHERE (tbl_name = '" . $tablename . "');");
00152   if ($result === false) return false;
00153 
00154   $all = db_fetch_array($result);
00155   $origsql = trim(preg_replace("/[\s]+/", " ", str_replace(",", ", ", preg_replace("/[\(]/", "( ", $all[0], 1))));
00156   $origsql = substr($origsql, 0, strlen($origsql)-1);
00157   $oldcols = preg_split("/[,]+/", substr(trim($origsql), strpos(trim($origsql), '(') + 1), -1, PREG_SPLIT_NO_EMPTY);
00158 
00159   $colnames = array();
00160   $coltype = array();
00161   for($i = 0;$i < sizeof($oldcols);$i++) {
00162     $colparts = preg_split("/[\s]+/", $oldcols[$i], -1, PREG_SPLIT_NO_EMPTY);
00163     $colnames[] = $colparts[0];
00164     $coltype[] = implode(" ", array_slice($colparts, 1));
00165   }
00166 
00167   return ($type ? $coltype : $colnames);
00168 }
