00307 function __alter_table($table, $alterdefs)
00308 {
00309   global $g_current_db;
00310 
00311   $sql = "SELECT sql,name,type FROM sqlite_master WHERE tbl_name = '" . $table . "' ORDER BY type DESC";
00312   $result = sqlite_query($g_current_db, $sql);
00313 
00314   if (($result === false) || (sqlite_num_rows($result) <= 0)) {
00315     trigger_error('no such table: ' . $table, E_USER_WARNING);
00316     return false;
00317   }
00318   // ------------------------------------- Build the queries
00319   $row = sqlite_fetch_array($result);
00320   $tmpname = 't' . time();
00321   $origsql = trim(preg_replace("/[\s]+/", " ", str_replace(",", ", ", preg_replace("/[\(]/", "( ", $row['sql'], 1))));
00322   $createtemptableSQL = 'CREATE TEMPORARY ' . substr(trim(preg_replace("'" . $table . "'", $tmpname, $origsql, 1)), 6);
00323   $origsql = substr($origsql, 0, strlen($origsql)-1); // chops the ) at end
00324   $createindexsql = array();
00325   $i = 0;
00326   $defs = preg_split("/[,]+/", $alterdefs, -1, PREG_SPLIT_NO_EMPTY);
00327   $prevword = $table;
00328   $oldcols = preg_split("/[,]+/", substr(trim($createtemptableSQL), strpos(trim($createtemptableSQL), '(') + 1), -1, PREG_SPLIT_NO_EMPTY);
00329   $oldcols = preg_split("/[,]+/", substr(trim($origsql), strpos(trim($origsql), '(') + 1), -1, PREG_SPLIT_NO_EMPTY);
00330   $newcols = array();
00331 
00332   for($i = 0;$i < sizeof($oldcols);$i++) {
00333     $colparts = preg_split("/[\s]+/", $oldcols[$i], -1, PREG_SPLIT_NO_EMPTY);
00334     $oldcols[$i] = $colparts[0];
00335     $newcols[$colparts[0]] = $colparts[0];
00336   }
00337 
00338   $newcolumns = '';
00339   $oldcolumns = '';
00340   reset($newcols);
00341 
00342   while (list($key, $val) = each($newcols)) {
00343     $newcolumns .= ($newcolumns?', ':'') . $val;
00344     $oldcolumns .= ($oldcolumns?', ':'') . $key;
00345   }
00346 
00347   $copytotempsql = 'INSERT INTO ' . $tmpname . '(' . $newcolumns . ') SELECT ' . $oldcolumns . ' FROM ' . $table;
00348   $dropoldsql = 'DROP TABLE ' . $table;
00349   $createtesttableSQL = $createtemptableSQL;
00350 
00351   $newname = "";
00352 
00353   foreach($defs as $def) {
00354     $defparts = preg_split("/[\s]+/", $def, -1, PREG_SPLIT_NO_EMPTY);
00355     $action = strtolower($defparts[0]);
00356 
00357     switch ($action) {
00358       case 'add':
00359 
00360         if (sizeof($defparts) <= 2) {
00367           return false;
00368         }
00369         $createtesttableSQL = substr($createtesttableSQL, 0, strlen($createtesttableSQL)-1) . ',';
00370         for($i = 1;$i < sizeof($defparts);$i++)
00371         $createtesttableSQL .= ' ' . $defparts[$i];
00372         $createtesttableSQL .= ')';
00373         break;
00374 
00375       case 'change':
00376 
00377         if (sizeof($defparts) <= 2) {
00378           trigger_error('near "' . $defparts[0] . ($defparts[1]?' ' . $defparts[1]:'') . ($defparts[2]?' ' . $defparts[2]:'') . '": SQLITE syntax error', E_USER_WARNING);
00379           return false;
00380         }
00381         if ($severpos = strpos($createtesttableSQL, ' ' . $defparts[1] . ' ')) {
00382           if ($newcols[$defparts[1]] != $defparts[1]) {
00383             trigger_error('unknown column "' . $defparts[1] . '" in "' . $table . '"', E_USER_WARNING);
00384             return false;
00385           }
00386           $newcols[$defparts[1]] = $defparts[2];
00387           $nextcommapos = strpos($createtesttableSQL, ',', $severpos);
00388           $insertval = '';
00389           for($i = 2;$i < sizeof($defparts);$i++)
00390           $insertval .= ' ' . $defparts[$i];
00391           if ($nextcommapos)
00392             $createtesttableSQL = substr($createtesttableSQL, 0, $severpos) . $insertval . substr($createtesttableSQL, $nextcommapos);
00393           else
00394             $createtesttableSQL = substr($createtesttableSQL, 0, $severpos - (strpos($createtesttableSQL, ',')?0:1)) . $insertval . ')';
00395         } else {
00396           trigger_error('unknown column "' . $defparts[1] . '" in "' . $table . '"', E_USER_WARNING);
00397           return false;
00398         }
00399         break;
00400 
00401       case 'drop';
00402 
00403         if (sizeof($defparts) < 2) {
00404           trigger_error('near "' . $defparts[0] . ($defparts[1]?' ' . $defparts[1]:'') . '": SQLITE syntax error', E_USER_WARNING);
00405           return false;
00406         }
00413         if (($severpos = strpos($createtesttableSQL, ' ' . $defparts[1] . ' ')) || ($severpos = strpos($createtesttableSQL, ' ' . $defparts[1] . ',')) || ($severpos = strpos($createtesttableSQL, ' ' . $defparts[1] . ')'))) {
00414           $nextcommapos = strpos($createtesttableSQL, ',', $severpos);
00415           if ($nextcommapos)
00416             $createtesttableSQL = substr($createtesttableSQL, 0, $severpos) . substr($createtesttableSQL, $nextcommapos + 1);
00417           else
00418             $createtesttableSQL = substr($createtesttableSQL, 0, $severpos - (strpos($createtesttableSQL, ',')?0:1)) . ')';
00419           unset($newcols[$defparts[1]]);
00420           /* RUBEM */ $createtesttableSQL = str_replace(",)", ")", $createtesttableSQL);
00421         } else {
00422           trigger_error('unknown column "' . $defparts[1] . '" in "' . $table . '"', E_USER_WARNING);
00423           return false;
00424         }
00425         break;
00426 
00427       case 'rename'; // RUBEM
00428         if (sizeof($defparts) < 2) {
00429           trigger_error('near "' . $defparts[0] . ($defparts[1]?' ' . $defparts[1]:'') . '": SQLITE syntax error', E_USER_WARNING);
00430           return false;
00431         }
00432         $newname = $defparts[2];
00433         break;
00434 
00435       default:
00436 
00437         trigger_error('near "' . $prevword . '": SQLITE syntax error', E_USER_WARNING);
00438         return false;
00439     } // switch
00440     $prevword = $defparts[sizeof($defparts)-1];
00441   } // foreach
00442   // This block of code generates a test table simply to verify that the columns specifed are valid
00443   // in an sql statement. This ensures that no reserved words are used as columns, for example
00444   sqlite_query($g_current_db, $createtesttableSQL);
00445   $err = sqlite_last_error($g_current_db);
00446   if ($err) {
00447     trigger_error("Invalid SQLITE code block: " . sqlite_error_string($err) . "\n", E_USER_WARNING);
00448     return false;
00449   }
00450   $droptempsql = 'DROP TABLE ' . $tmpname;
00451   sqlite_query($g_current_db, $droptempsql);
00452   // End test block
00453   // Is it a Rename?
00454   if (strlen($newname) > 0) {
00455     // $table = preg_replace("/([a-z]_)[a-z_]*/i", "\\1" . $newname, $table);
00456     // what do want with the regex? the expression should be [a-z_]! hans
00457     // why not just
00458     $table = $newname;
00459   }
00460   $createnewtableSQL = 'CREATE ' . substr(trim(preg_replace("'" . $tmpname . "'", $table, $createtesttableSQL, 1)), 17);
00461 
00462   $newcolumns = '';
00463   $oldcolumns = '';
00464   reset($newcols);
00465 
00466   while (list($key, $val) = each($newcols)) {
00467     $newcolumns .= ($newcolumns?', ':'') . $val;
00468     $oldcolumns .= ($oldcolumns?', ':'') . $key;
00469   }
00470   $copytonewsql = 'INSERT INTO ' . $table . '(' . $newcolumns . ') SELECT ' . $oldcolumns . ' FROM ' . $tmpname;
00471   // ------------------------------------- Perform the actions
00472   if (sqlite_query($g_current_db, $createtemptableSQL) === false) return false; //create temp table
00473   if (sqlite_query($g_current_db, $copytotempsql) === false) return false; //copy to table
00474   if (sqlite_query($g_current_db, $dropoldsql) === false) return false; //drop old table
00475   if (sqlite_query($g_current_db, $createnewtableSQL) === false) return false; //recreate original table
00476   if (sqlite_query($g_current_db, $copytonewsql) === false) return false; //copy back to original table
00477   if (sqlite_query($g_current_db, $droptempsql) === false) return false; //drop temp table
00478   return true;
00479 }
